import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.BN2sqjC1.js";const h=JSON.parse('{"title":"Indice degli ADR","description":"","frontmatter":{},"headers":[],"relativePath":"adr/index.md","filePath":"adr/README.md"}'),d={name:"adr/index.md"};function r(n,e,l,c,s,p){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="indice-degli-adr" tabindex="-1">Indice degli ADR <a class="header-anchor" href="#indice-degli-adr" aria-label="Permalink to &quot;Indice degli ADR&quot;">​</a></h1><p>Le deviazioni e le precisazioni rispetto a <code>Specifications.md</code> si registrano come ADR (template: <a href="./0000-template.html"><code>0000-template.md</code></a>). Gli ADR in stato <strong>proposta</strong> vanno recepiti nello spec dall&#39;owner; quelli <strong>accettata</strong> sono già confermati. Elenco verificato rispetto al contenuto della directory.</p><table tabindex="0"><thead><tr><th>ADR</th><th>Titolo</th><th>Stato</th></tr></thead><tbody><tr><td><a href="./0001-url-scheme-delivery.html">0001</a></td><td>Consegna degli URL <code>memobrain://</code> per sistema operativo (SPIKE-01)</td><td>accettata</td></tr><tr><td><a href="./0002-sqlite-fts5-trigram.html">0002</a></td><td>SQLite pure-Go con FTS5 <code>trigram</code> per l&#39;indice locale (SPIKE-02)</td><td>accettata</td></tr><tr><td><a href="./0003-react-excalidraw.html">0003</a></td><td>React 19 e strategia per Excalidraw (SPIKE-03)</td><td>accettata</td></tr><tr><td><a href="./0004-live-preview.html">0004</a></td><td>Architettura Live Preview, una sola vista CodeMirror (SPIKE-04)</td><td>superata in parte da ADR-0049 (Source e Reading restano)</td></tr><tr><td><a href="./0005-webview-csp.html">0005</a></td><td>Content Security Policy nel webview (SPIKE-05)</td><td>accettata</td></tr><tr><td><a href="./0006-go-toolchain-and-tools-module.html">0006</a></td><td>Go 1.26 e modulo <code>tools/</code> per gli strumenti di sviluppo</td><td>accettata</td></tr><tr><td><a href="./0007-dev-stack.html">0007</a></td><td>Stack di sviluppo locale: RustFS come S3, porte non standard</td><td>accettata</td></tr><tr><td><a href="./0008-client-config-endpoint.html">0008</a></td><td>Endpoint pubblico <code>GET /client-config</code> per il bootstrap</td><td>accettata</td></tr><tr><td><a href="./0009-sync-protocol-details.html">0009</a></td><td>Dettagli del protocollo di sync (M2)</td><td>accettata</td></tr><tr><td><a href="./0010-drawing-and-canvas-details.html">0010</a></td><td>Dettagli di disegni e canvas (M3)</td><td>accettata</td></tr><tr><td><a href="./0011-sharing-groups-config-details.html">0011</a></td><td>Condivisione, gruppi e configurazione distribuita (M4)</td><td>accettata</td></tr><tr><td><a href="./0012-admin-export-details.html">0012</a></td><td>Console admin ed export, ruoli minimi del service account (M5)</td><td>accettata</td></tr><tr><td><a href="./0013-graph-view-details.html">0013</a></td><td>Graph view: Canvas 2D, ctime da frontmatter/mtime (M6-WP1)</td><td>accettata</td></tr><tr><td><a href="./0014-bases-details.html">0014</a></td><td>Bases: sottoinsieme supportato, degrado e round-trip</td><td>accettata</td></tr><tr><td><a href="./0015-daily-templates-composer-details.html">0015</a></td><td>Note giornaliere, template, composer (M6)</td><td>accettata</td></tr><tr><td><a href="./0016-bookmarks-workspaces-preview-details.html">0016</a></td><td>Bookmarks, workspaces e page preview</td><td>accettata</td></tr><tr><td><a href="./0017-importer-details.html">0017</a></td><td>Importer: mappature per sorgente e limiti</td><td>accettata</td></tr><tr><td><a href="./0018-local-history-details.html">0018</a></td><td>History locale e File recovery (M6-WP5)</td><td>accettata</td></tr><tr><td><a href="./0019-embedded-search-export-details.html">0019</a></td><td>Embedded search, export PDF/HTML, impostazioni residue (M6-WP6)</td><td>accettata</td></tr><tr><td><a href="./0020-performance-details.html">0020</a></td><td>Prestazioni: indicizzazione a lotti, cache di ricerca, albero virtualizzato (M7-WP1)</td><td>accettata</td></tr><tr><td><a href="./0021-security-privacy-details.html">0021</a></td><td>Sicurezza e privacy: GDPR (export e cancellazione), controlli in CI (M7-WP2)</td><td>accettata</td></tr><tr><td><a href="./0022-resilience-details.html">0022</a></td><td>Resilienza: garanzie verificate, bug trovati, prova di ripristino (M7-WP2b)</td><td>accettata</td></tr><tr><td><a href="./0023-distribution-and-updates-details.html">0023</a></td><td>Distribuzione e aggiornamenti: manifest firmato, installer, chart (M7-WP3)</td><td>proposta</td></tr><tr><td><a href="./0024-excalidraw-feature-parity.html">0024</a></td><td>Parità funzionale con i plugin Excalidraw ed Excalidraw Extras di terze parti</td><td>accettata</td></tr><tr><td><a href="./0025-desktop-frontend-esbuild.html">0025</a></td><td>Frontend desktop e Web UI: build e dev server con esbuild al posto di Vite</td><td>accettata</td></tr><tr><td><a href="./0026-shell-ui-revisione.html">0026</a></td><td>Revisione della shell UI desktop: ribbon, sidebar, footer, tab bloccabili (M8)</td><td>accettata</td></tr><tr><td><a href="./0027-slides-note.html">0027</a></td><td>Slides: presentazione di note (M8-WP8)</td><td>accettata</td></tr><tr><td><a href="./0028-excalidraw-fork.html">0028</a></td><td>Excalidraw: fork con lazo, secchiello e disegna per la forma</td><td>accettata</td></tr><tr><td><a href="./0029-web-workbench.html">0029</a></td><td>Workbench del vault nella Web UI (M9)</td><td>accettata</td></tr><tr><td><a href="./0030-desktop-core-wasm.html">0030</a></td><td>Core del desktop compilato in WebAssembly per il workbench web (M9)</td><td>accettata</td></tr><tr><td><a href="./0031-release-pipeline-unsigned-channel.html">0031</a></td><td>Pipeline di rilascio: correzioni, canale non firmato, matrice estesa (M10)</td><td>accettata</td></tr><tr><td><a href="./0032-task-runner.html">0032</a></td><td>Task (go-task) al posto di make</td><td>accettata</td></tr><tr><td><a href="./0033-sqlc-per-module.html">0033</a></td><td>Un pacchetto sqlc per modulo e proprietà delle tabelle nel cloud; Excalidraw offline</td><td>accettata</td></tr><tr><td><a href="./0034-envelope-aad.html">0034</a></td><td>Envelope della VMK legati al vault e al tipo (formato v2 con AAD)</td><td>accettata</td></tr><tr><td><a href="./0035-status-bar-opzionale.html">0035</a></td><td>Barra di stato compatta e opzionale</td><td>accettata</td></tr><tr><td><a href="./0036-verifiche-locali-senza-ci.html">0036</a></td><td>Verifiche locali (<code>task ci</code>) al posto di un servizio di CI</td><td>accettata</td></tr><tr><td><a href="./0037-registro-funzioni-e-cloud-features.html">0037</a></td><td>Registro delle funzioni, <code>@memobrain/cloud-features</code> con CloudPort e client Go generato</td><td>accettata</td></tr><tr><td><a href="./0038-retention-e-finestra-changelog.html">0038</a></td><td>Retention delle revisioni, compattazione del changelog e copie di conflitto</td><td>accettata</td></tr><tr><td><a href="./0039-sync-db-candidati-e-quarantena.html">0039</a></td><td>sync.db: candidati al merge persistenti e quarantena dei path illeggibili</td><td>accettata</td></tr><tr><td><a href="./0040-move-prefix-rename-cartelle-condivise.html">0040</a></td><td><code>move_prefix</code> resta il rename atomico delle cartelle condivise</td><td>accettata</td></tr><tr><td><a href="./0041-control-plane-ruoli-identita-account.html">0041</a></td><td>Control plane del cloud: ruolo autorevole dopo un cambio, conflitti di identità, eliminazione unificata degli account, rubrica, notifiche</td><td>accettata</td></tr><tr><td><a href="./0042-path-token-legato-al-file.html">0042</a></td><td>Token di path dei vault privati legati al file (formato enc2)</td><td>accettata</td></tr><tr><td><a href="./0043-convergenza-ui-console-workbench.html">0043</a></td><td>Convergenza degli stack UI di console e workbench (primitive in <code>@memobrain/ui</code>)</td><td>accettata</td></tr><tr><td><a href="./0044-watcher-fsevents-macos.html">0044</a></td><td>Watcher su macOS con FSEvents (via purego) al posto di kqueue; limiti di inotify</td><td>accettata</td></tr><tr><td><a href="./0045-parita-per-costruzione.html">0045</a></td><td>Parità per costruzione tra desktop, workbench web e console (M12)</td><td>accettata</td></tr><tr><td><a href="./0046-bootstrap-server-indietro.html">0046</a></td><td>Bootstrap quando il server è tornato indietro (PITR): ripubblicare, non cancellare (integra ADR-0022)</td><td>accettata</td></tr><tr><td><a href="./0047-apertura-file-per-tipo-e-presentazioni-marp.html">0047</a></td><td>Apertura dei file per tipo (app del SO / download) e presentazioni Marp in file <code>.marp</code></td><td>accettata; parzialmente superata da ADR-0048</td></tr><tr><td><a href="./0048-presentazioni-marp-slideshow-ribbon-pptx.html">0048</a></td><td>Presentazioni Marp: editor a tutta larghezza, tab SlideShow, export nel ribbon e PPTX modificabile (supera in parte ADR-0047)</td><td>accettata</td></tr><tr><td><a href="./0049-editor-live-milkdown.html">0049</a></td><td>Editor Live su Milkdown (Crepe) con strato di conservazione del sorgente (supera in parte ADR-0004); unico motore Live dal 2026-11-12 (A-W9), prove manuali di A-W8 ancora da fare</td><td>accettata (non recepita nello spec)</td></tr><tr><td><a href="./0050-ai-inattiva-e-collab-spento.html">0050</a></td><td>AI implementata ma inattiva e collaborazione in tempo reale spenta (doppio cancello: flag e costante di build; la collaborazione ha anche il cancello del provider)</td><td>proposta</td></tr><tr><td><a href="./0051-wails-v3.html">0051</a></td><td>Migrazione del client desktop a Wails v3.1.0, solo parità (devia da V-07, D-07, A-03); implementato e rilasciato dalla 1.4.0, matrice manuale B-W8 da eseguire</td><td>accettata (2026-11-20; recepita nello spec v1.8)</td></tr><tr><td><a href="./0052-rebrand-clarae-notanda.html">0052</a></td><td>Rebrand a «Clarae notanda» (M17): migrazione automatica, etichette crittografiche congelate, percorsi legacy, allowlist; devia dallo spec</td><td>accettata (recepita nello spec v1.7)</td></tr><tr><td><a href="./0053-navigazione-dei-disegni.html">0053</a></td><td>Navigazione dei disegni: zoom sulla selezione e mini-mappa (M18); gruppo flottante al posto dello slot del footer, stato per dispositivo</td><td>accettata (recepita nello spec v1.6)</td></tr><tr><td><a href="./0054-editor-dei-disegni-merge-undo-ricarica-libreria-ricerca.html">0054</a></td><td>Editor dei disegni: merge delle modifiche non salvate (D-04 con l&#39;autore in <code>sync.db</code>), undo, ricarica, auto-export ritardato, anteprime per tema, libreria fusa per id, ricerca su <code>originalText</code> e TeX (M18); emenda ADR-0010; devia da §3.4.5 e §3.4.6</td><td>accettata (recepita nello spec v1.6)</td></tr><tr><td><a href="./0055-grafo-3d.html">0055</a></td><td>Grafo del vault in 3D (<code>3d-force-graph</code>) e disegni, lavagne e basi come nodi (M18-D): interruttore nella vista, tre livelli di dettaglio, layout nel worker, tetto di 5.000 nodi; aggiunta a ADR-0013</td><td>accettata (recepita nello spec v1.6)</td></tr><tr><td><a href="./0056-applicazioni-in-vista-nativa.html">0056</a></td><td>Applicazioni: pagine web registrate nel vault (file <code>.webapp</code>) in una vista nativa sovrapposta alla scheda (M18-E): solo macOS con driver, nel browser di sistema altrove, sessioni per vault fuori dal vault con pulizia degli archivi orfani, <code>features.web_viewer</code> spento di default (ADR-0060, accettata, lo accende dalla 1.7.2); anticipa il Web viewer da P2</td><td>accettata (recepita nello spec v1.6)</td></tr><tr><td><a href="./0057-identita-dispositivo-desktop-hostname.html">0057</a></td><td>Identità del dispositivo desktop per hostname (indice unico parziale, upsert alla registrazione) e revoca al logout (M21); devia da §1.7, §3.2.2 e §3.5.1</td><td>accettata (recepita nello spec v1.7)</td></tr><tr><td><a href="./0058-logout-completo-da-keycloak.html">0058</a></td><td>Logout completo da Keycloak (M21): console con revoca dei token, pagina <code>/signed-out</code> e <code>prompt=login</code>; desktop con revoca dalla discovery, logout back-channel e <code>prompt=login</code>; integra §1.3 e D-08</td><td>accettata (recepita nello spec v1.7)</td></tr><tr><td><a href="./0059-pulizia-cartella-configurazione-legacy-e-zip-coerente.html">0059</a></td><td>Pulizia della cartella di configurazione legacy dopo l&#39;aggiornamento e ZIP coerente (M21): emenda ADR-0052 («mai cancellazioni»); devia da §2.8.2 e §3.5.2; la parte sincronizzata richiede un cloud 1.7 o successivo</td><td>accettata (recepita nello spec v1.7)</td></tr><tr><td><a href="./0060-web-viewer-acceso-di-default.html">0060</a></td><td><code>features.web_viewer</code> acceso di default (decisione dell&#39;owner del 2026-11-15), pulsante e voce di menu «Nuova applicazione» nell&#39;esploratore e nomi senza <code>.webapp</code> (M21); emenda ADR-0056; devia da §2.6.6</td><td>accettata (recepita nello spec v1.7)</td></tr><tr><td><a href="./0061-budget-iniziale-console-720.html">0061</a></td><td>Budget iniziale della console da 700 a 720 kB (M21): la console resta un file unico coperto da SRI; emenda ADR-0020</td><td>accettata (recepita nello spec v1.7)</td></tr><tr><td><a href="./0062-vista-integrata-windows-linux.html">0062</a></td><td>Vista integrata delle applicazioni accesa di default su Windows (driver WebView2 senza interruttore) e Linux (nuovo driver WebKitGTK), con ripiego automatico a «Apri nel browser» e <code>CLARAE_WEBVIEW=off</code> (M22); emenda ADR-0056 (punti 2, 17, 34-36) e ADR-0060; devia da §2.2.1, §2.6.6, §3.7, §4.2 e C.2; prove reali a carico dell&#39;owner</td><td>accettata (2026-11-20; recepita nello spec v1.8)</td></tr><tr><td><a href="./0063-nomi-file-senza-estensione.html">0063</a></td><td>Nomi dei file senza estensione per ciò che si apre in una scheda (<code>openTarget</code> = <code>in-app</code>), helper unico <code>splitName</code>/<code>displayName</code> e rinomina che conserva l&#39;estensione (M22); integra ADR-0047; nessuna modifica Go</td><td>accettata (2026-11-20; recepita nello spec v1.8)</td></tr><tr><td><a href="./0064-terminale-integrato-e-finestra-separata.html">0064</a></td><td>Terminale integrato nel client desktop (shell dell&#39;utente in PTY: <code>creack/pty</code> e ConPTY; xterm.js lazy; I/O da binding ed eventi) con più tab, pannello ancorabile e finestra Wails v3 separata per il solo terminale, sessioni che sopravvivono allo sgancio, chiusura senza orfani, nessun flag del Config Profile, non aperto nei vault in sola lettura (<code>terminal-read-only</code>) e non nel workbench web (M23); emenda ADR-0051 («niente pop-out»); devia da A-03, §2.2.1 (pop-out), §2.5, §2.8.3, §3.7, §4.2, App. B e C.2</td><td>accettata (2026-11-20; recepita nello spec v1.8)</td></tr><tr><td><a href="./0065-presenza-in-tempo-reale.html">0065</a></td><td>Presenza in tempo reale sui vault condivisi (avatar degli altri utenti sullo stesso file e cursori live; WebSocket <code>GET /api/v1/presence</code> e PostgreSQL <code>LISTEN/NOTIFY</code> tra repliche; <code>features.presence</code> acceso di default; componenti <code>Avatar</code>/<code>AvatarGroup</code> propri in <code>@clarae/ui</code>; nessun co-editing, nessuna persistenza) (M25); emenda ADR-0060 (via il pulsante «Nuova applicazione» dall&#39;esploratore) e ADR-0050 (non accende il co-editing); devia da A-05, §2.6.4, D-04, V-01 e §3.7</td><td>accettata (2026-11-20; recepita nello spec v1.9)</td></tr><tr><td><a href="./0066-vcs-esclusi-e-file-non-inviati.html">0066</a></td><td>Cartelle dei sistemi di versione (<code>.git</code>, <code>.hg</code>, <code>.svn</code>, <code>.bzr</code>, <code>.jj</code>, a qualunque profondità) sempre fuori dalla sincronizzazione, righe diventate escluse dimenticate senza cancellazioni (le copie nel cloud restano) ed elenco dei file non inviati con il motivo in Impostazioni › Sincronizzazione (<code>SyncAPI.Unsent</code>, «Riprova») (M26); devia da §3.4.2, §3.4.3 e §3.4.4 A</td><td>accettata (2026-11-21)</td></tr><tr><td><a href="./0067-sito-documentazione-github-pages.html">0067</a></td><td>Sito della documentazione generato con VitePress da <code>docs/</code> in <code>docs_html/</code> e pubblicato sul branch <code>gh-pages</code> per GitHub Pages da <code>task docs-publish</code> e dal workflow <code>docs.yml</code>, eccezione dichiarata ad ADR-0036 (nessun controllo nel workflow); devia dalla riga «Branching/verifiche» di §6 e dall&#39;Appendice C</td><td>proposta</td></tr></tbody></table><p>Nota: gli ADR 0015 e 0018 usano un&#39;intestazione in forma di elenco invece della tabella del template; il contenuto resta valido, l&#39;uniformazione del formato è un&#39;attività di pulizia non bloccante. Gli ADR 0036–0044 sono recepiti in <code>Specifications.md</code> v1.2, gli ADR 0029, 0030 e 0032 nella v1.3 gli ADR 0009–0022, 0024, 0026–0028, 0031, 0033 e 0034 nella v1.4 <a href="./0035-status-bar-opzionale.html">ADR-0035</a> (barra di stato opzionale, spenta per default) nella v1.5 e gli ADR 0053–0056 nella v1.6 (Appendice C.4). Resta in stato <strong>proposta</strong>, e non è recepito nello spec, solo <a href="./0023-distribution-and-updates-details.html">ADR-0023</a> (manifest di aggiornamento firmato e installer firmati, mai attivati). La raccolta <a href="./../spec-v1.2-proposta.html"><code>../spec-v1.2-proposta.md</code></a> è stata recepita nella v1.4, salvo ADR-0023 e ADR-0035 (recepito poi nella v1.5). Gli ADR 0045 e 0046 (M12) sono accettati ma non ancora recepiti nello spec: ADR-0046 devia da §3.4.4 (cestino locale solo per una finestra del changelog scaduta) e richiede l&#39;aggiornamento di <code>Specifications.md</code> da parte dell&#39;owner. L&#39;ADR-0049 (M16) è <strong>accettato</strong> il 2026-11-12 per decisione dell&#39;owner, ma non è ancora recepito nello spec (devia da §2.3, §3.4.2 e §4.2): Milkdown è l&#39;unico motore Live e il CodeMirror Live Preview è rimosso (A-W9), mentre le prove manuali del cancello A-W8 (IME, spellcheck e lettori di schermo sulle tre WebView) restano da fare. <a href="./0050-ai-inattiva-e-collab-spento.html">ADR-0050</a> (M15) è in stato <strong>proposta</strong>: non è accettato né recepito nello spec (devia da §2.3.2 e §2.6.6). <a href="./0051-wails-v3.html">ADR-0051</a> (M16) è <strong>accettata</strong> il 2026-11-20 (opzione A della proposta di spec v1.8) e <strong>recepita in <code>Specifications.md</code> v1.8</strong> (V-07, D-07, A-03, §1.3, §2.3.2, §2.5, §4.2, §4.5, C.2 e C.4). L&#39;AI e la collaborazione (ADR-0050) esistono nel codice ma dietro costanti di build spente, quindi non sono visibili all&#39;utente; la migrazione a Wails v3 (B-W0…B-W7) è nel codice e l&#39;app desktop gira su v3 su macOS, mentre la matrice manuale su Windows e Linux (B-W8) e la revisione finale (B-W9) sono da fare. Gli spike sono stati eseguiti il 2026-11-10: per ADR-0049 alla lettera del piano è un NO-GO (criteri 1, 2 e 5 falliti; le condizioni per il GO sono state poi attuate), per ADR-0051 un GO con condizioni. ADR-0004 è parzialmente superata da ADR-0049 (Source e Reading restano). Quando ADR-0050 sarà accettato vanno aggiornati gli altri ADR elencati nelle sue sezioni «Conseguenze»; per ADR-0051 gli ADR da riallineare (0001, 0005, 0023, 0025, 0029, 0030, 0031) portano note di emendamento (2026-11-20). <a href="./0052-rebrand-clarae-notanda.html">ADR-0052</a> (M17, rebrand) è <strong>accettata</strong> il 2026-11-16 per decisione dell&#39;owner ed è <strong>recepita in <code>Specifications.md</code> v1.7</strong> (2026-11-16), a partire dalla sezione «Sostituzioni da riportare in <code>Specifications.md</code>» dell&#39;ADR (la sintesi, con le eccezioni che restano, è in <a href="./../spec-v1.7-proposta.html"><code>../spec-v1.7-proposta.md</code></a>); il rename è già eseguito (1.5.0, pubblicata come 1.5.1). Gli ADR 0053, 0054, 0055 e 0056 (M18: navigazione dei disegni, editor dei disegni, grafo 3D, applicazioni) sono <strong>accettati</strong> il 2026-11-15 per decisione dell&#39;owner e <strong>recepiti in <code>Specifications.md</code> v1.6</strong> (Appendice C.4), già implementati (1.6.0, 1.7.0 e 1.7.1). ADR-0053 è un&#39;aggiunta a §2.7.2; ADR-0054 devia da §3.4.5 e §3.4.6 (la libreria di forme si fonde per id) e precisa §2.7.1, §2.7.2, §2.7.3 e §3.4.3 (colonna <code>head_author</code> di <code>sync.db</code>); ADR-0055 è un&#39;aggiunta a ADR-0013 (§2.2.1, §3.4.6, §4.2, Appendice A); ADR-0056 anticipa il Web viewer da P2 (§2.2.1, §2.6.6, §3.7, §4.2, Appendici B e C.2). Il recepimento della v1.6 non tocca gli ADR 0045–0052: lo spec v1.6 dice ancora Wails v2 e <em>MemoBrain Notes</em> (<code>.memobrain/</code>), e il testo aggiunto dalla v1.6 segue quella nomenclatura (nel codice sono <em>Clarae notanda</em> e <code>.clarae/</code>, ADR-0052, recepito nella v1.7). <code>features.web_viewer</code> è spento di default nello spec v1.6 e nella 1.7.1 (decisione dell&#39;owner per la 1.7.1; con ADR-0060, accettata il 2026-11-16, è acceso dalla 1.7.2, come dice lo spec v1.7): la matrice manuale <a href="./../qa/m18-webview-matrice.html"><code>m18-webview-matrice.md</code></a> non è eseguita, e nulla del frontend delle applicazioni né del grafo 3D è provato sulla finestra reale; il runbook delle prove è <a href="./../qa/verifica-manuale-1.7.html"><code>verifica-manuale-1.7.md</code></a>. Gli ADR 0057, 0058, 0059, 0060 e 0061 (M21, correttivi dello schizzo del 2026-11-15 e budget della console) sono <strong>accettati</strong> il 2026-11-16 per decisione dell&#39;owner, già implementati (1.7.2), e <strong>recepiti in <code>Specifications.md</code> v1.7</strong> (2026-11-16), secondo <a href="./../spec-v1.7-proposta.html"><code>../spec-v1.7-proposta.md</code></a>, che resta come storia del recepimento. ADR-0057 devia da §1.7, §3.2.2 e §3.5.1 (identità del dispositivo desktop per hostname, con l&#39;elenco di §2.6.1); ADR-0058 integra §1.3 e §3.3.1 (logout); ADR-0059 emenda ADR-0052 e devia da §2.8.2 e §3.5.2 (path dello ZIP); ADR-0060 emenda ADR-0056 e devia da §2.6.6 (<code>features.web_viewer</code> acceso di default, decisione dell&#39;owner), con le note di §2.2.1, C.2 e C.4; <a href="./0061-budget-iniziale-console-720.html">ADR-0061</a> alza il budget iniziale della console da 700 a 720 kB (§4.4 e C.4) ed emenda ADR-0020. Fino al recepimento lo spec v1.6 resta com&#39;è. Gli ADR 0062 e 0063 (M22, richiesta dell&#39;owner del 2026-11-19) e <a href="./0064-terminale-integrato-e-finestra-separata.html">ADR-0064</a> (M23, richiesta dell&#39;owner del 2026-11-20) sono <strong>accettati</strong> il 2026-11-20 per decisione dell&#39;owner e <strong>recepiti in <code>Specifications.md</code> v1.8</strong> (2026-11-20), insieme a ADR-0051 (opzione A), secondo <a href="./../spec-v1.8-proposta.html"><code>../spec-v1.8-proposta.md</code></a>, che resta come storia del recepimento. ADR-0062 e ADR-0063 sono implementati e rilasciati (1.7.3); ADR-0064 è implementato in M23 (lo spec lo dichiara «M23 (1.8.0)», il tag seguirà) e <strong>non è provato su una finestra reale</strong>. ADR-0062 emenda ADR-0056 e ADR-0060 (vista integrata anche su Windows e Linux, con ripiego automatico) e devia da §2.2.1, §2.6.6, §3.7, §4.2 e C.2 (i driver di Windows e di Linux non sono provati su una finestra reale); ADR-0063 integra ADR-0047 e non devia dallo spec (aggiornato il nome senza <code>.webapp</code> nella riga «Web viewer» di §2.2.1); ADR-0064 (terminale integrato con una seconda finestra Wails v3 solo per il terminale) emenda ADR-0051 («niente pop-out») e devia da A-03, dalla riga «Finestre separate (pop-out)» di §2.2.1 e da §2.5, §2.8.3, §3.7, §4.2, App. B e C.2; il workbench web non lo ha (eccezione di parità) e non c&#39;è un flag del Config Profile. Lo spec v1.8 dice Wails v3.1.0.</p>',4)])])}const u=t(d,[["render",r]]);export{h as __pageData,u as default};
